pub type AppError = Failed(String)

record Fetcher {
    seed: Int64
}

impl Fetcher {
    fn fetch(self) -> Result<Int64, AppError> {
        return Ok(self.seed)
    }
}

pub fn main() -> Result<(), AppError> {
    let f = Fetcher { seed: 1 }
    let v = f.fetch()?
    return Ok(())
}
